python -c "
import json,re,glob,os
names=set()
for nb in glob.glob('notebooks/*.ipynb'):
    d=json.load(open(nb))
    for c in d['cells']:
        if c['cell_type']!='code': continue
        s=''.join(c['source'])
        for m in re.finditer(r'from mlp[\w.]* import ([^\n]+)', s):
            names.add((os.path.basename(nb), m.group(1).strip()))
for n in sorted(names): print(n)
"
